{
  "name": "ssg",
  "version": "1.0.0",
  "description": "A static site generator CLI in TypeScript",
  "type": "commonjs",
  "main": "dist/index.js",
  "bin": {
    "ssg": "dist/cli.js"
  },
  "scripts": {
    "build": "tsc",
    "test": "jest",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "gray-matter": "^4.0.3",
    "marked": "^14.1.2"
  },
  "devDependencies": {
    "@types/jest": "^29.5.13",
    "@types/node": "^22.7.4",
    "jest": "^29.7.0",
    "ts-jest": "^29.2.5",
    "typescript": "^5.6.2"
  }
}

export interface Frontmatter {
  title?: string;
  date?: Date | string;
  tags?: string[];
}

export interface Page {
  slug: string;
  title: string;
  date: Date;
  tags: string[];
  html: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Frontmatter, Page } from './types';

export function parseMarkdown(raw: string): { data: Frontmatter; content: string } {
  const { data, content } = matter(raw);
  return { data: data as Frontmatter, content };
}

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown, { async: false }) as string;
}

export function toDate(value: Date | string | undefined): Date {
  if (value instanceof Date) return value;
  if (typeof value === 'string') {
    const parsed = new Date(value);
    if (!Number.isNaN(parsed.getTime())) return parsed;
  }
  return new Date(0);
}

export function readMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }
  return fs
    .readdirSync(contentDir)
    .filter((file) => file.endsWith('.md') || file.endsWith('.markdown'))
    .sort();
}

export function buildPage(slug: string, raw: string): Page {
  const { data, content } = parseMarkdown(raw);
  const html = markdownToHtml(content);
  return {
    slug,
    title: typeof data.title === 'string' ? data.title : slug,
    date: toDate(data.date),
    tags: Array.isArray(data.tags) ? data.tags.map(String) : [],
    html,
  };
}

export function sortByDate(pages: Page[]): Page[] {
  return [...pages].sort((a, b) => b.date.getTime() - a.date.getTime());
}

export function loadPages(contentDir: string): Page[] {
  const files = readMarkdownFiles(contentDir);
  const pages = files.map((file) => {
    const raw = fs.readFileSync(path.join(contentDir, file), 'utf-8');
    const slug = path.basename(file, path.extname(file));
    return buildPage(slug, raw);
  });
  return sortByDate(pages);
}

import { Page } from './types';

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function formatDate(date: Date): string {
  if (date.getTime() === 0) return '';
  return date.toISOString().slice(0, 10);
}

export function renderPage(page: Page, pages: Page[]): string {
  const tagsHtml = page.tags.length
    ? `<ul class="tags">${page.tags
        .map((tag) => `<li>${escapeHtml(tag)}</li>`)
        .join('')}</ul>`
    : '';
  const dateHtml = page.date.getTime()
    ? `<time datetime="${escapeHtml(page.date.toISOString())}">${formatDate(page.date)}</time>`
    : '';
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${escapeHtml(page.title)}</title>
</head>
<body>
  <header>
    <nav><a href="index.html">Home</a></nav>
  </header>
  <main>
    <article>
      <h1>${escapeHtml(page.title)}</h1>
      ${dateHtml}
      ${tagsHtml}
      <div class="content">
${page.html}
      </div>
    </article>
  </main>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const dateHtml = page.date.getTime()
        ? ` — <time datetime="${escapeHtml(page.date.toISOString())}">${formatDate(page.date)}</time>`
        : '';
      const tagsHtml = page.tags.length
        ? ` [${page.tags.map((tag) => escapeHtml(tag)).join(', ')}]`
        : '';
      return `<li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(
        page.title
      )}</a>${dateHtml}${tagsHtml}</li>`;
    })
    .join('\n');
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Index</title>
</head>
<body>
  <header>
    <h1>Index</h1>
  </header>
  <main>
    <ul class="posts">
${items || '      <li>No posts</li>'}
    </ul>
  </main>
</body>
</html>
`;
}

import fs from 'fs';
import path from 'path';
import { BuildOptions, Page } from './types';
import { loadPages } from './markdown';
import { renderIndex, renderPage } from './templates';

export function build(options: BuildOptions): Page[] {
  const pages = loadPages(options.contentDir);
  const outputDir = options.outputDir;
  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const html = renderPage(page, pages);
    fs.writeFileSync(path.join(outputDir, `${page.slug}.html`), html, 'utf-8');
  }

  const indexHtml = renderIndex(pages);
  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml, 'utf-8');

  return pages;
}

import { Frontmatter, Page, BuildOptions } from './types';
import { parseMarkdown, markdownToHtml, toDate, buildPage, sortByDate, loadPages, readMarkdownFiles } from './markdown';
import { escapeHtml, formatDate, renderIndex, renderPage } from './templates';
import { build } from './generate';

export {
  Frontmatter,
  Page,
  BuildOptions,
  parseMarkdown,
  markdownToHtml,
  toDate,
  buildPage,
  sortByDate,
  loadPages,
  readMarkdownFiles,
  escapeHtml,
  formatDate,
  renderIndex,
  renderPage,
  build,
};

import { build } from './generate';

export interface CliOptions {
  command: string;
  contentDir: string;
  outputDir: string;
}

export function parseArgs(argv: string[]): CliOptions {
  const args = argv.slice(2);
  const options: CliOptions = {
    command: '',
    contentDir: './content',
    outputDir: './dist',
  };

  let i = 0;
  while (i < args.length) {
    const arg = args[i];
    if (arg === '--content') {
      options.contentDir = args[++i];
    } else if (arg === '--output') {
      options.outputDir = args[++i];
    } else if (arg.startsWith('--content=')) {
      options.contentDir = arg.slice('--content='.length);
    } else if (arg.startsWith('--output=')) {
      options.outputDir = arg.slice('--output='.length);
    } else if (!arg.startsWith('-')) {
      if (!options.command) options.command = arg;
    }
    i++;
  }

  return options;
}

export function run(argv: string[]): number {
  const options = parseArgs(argv);
  if (options.command !== 'build') {
    console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
    return 1;
  }

  try {
    const pages = build({
      contentDir: options.contentDir,
      outputDir: options.outputDir,
    });
    console.log(`Generated ${pages.length} page(s) in ${options.outputDir}`);
    return 0;
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    return 1;
  }
}

if (require.main === module) {
  process.exit(run(process.argv));
}

import fs from 'fs';
import os from 'os';
import path from 'path';
import {
  parseMarkdown,
  markdownToHtml,
  toDate,
  buildPage,
  sortByDate,
  loadPages,
  build,
  escapeHtml,
} from '../src';

describe('parseMarkdown', () => {
  it('extracts title, date and tags from frontmatter', () => {
    const raw = `---
title: Hello World
date: 2024-01-15
tags:
  - a
  - b
---
# Body
`;
    const { data, content } = parseMarkdown(raw);
    expect(data.title).toBe('Hello World');
    expect(data.date).toBeInstanceOf(Date);
    expect((data.date as Date).toISOString().slice(0, 10)).toBe('2024-01-15');
    expect(data.tags).toEqual(['a', 'b']);
    expect(content.trim()).toBe('# Body');
  });
});

describe('markdownToHtml', () => {
  it('converts markdown to html', () => {
    expect(markdownToHtml('# Hi').trim()).toContain('<h1');
    expect(markdownToHtml('**bold**').trim()).toContain('<strong>bold</strong>');
  });
});

describe('toDate', () => {
  it('passes through Date objects', () => {
    const d = new Date('2020-05-05');
    expect(toDate(d).getTime()).toBe(d.getTime());
  });
  it('parses strings', () => {
    expect(toDate('2020-05-05').getTime()).toBe(new Date('2020-05-05').getTime());
  });
  it('falls back to epoch for invalid dates', () => {
    expect(toDate(undefined).getTime()).toBe(0);
    expect(toDate('not-a-date').getTime()).toBe(0);
  });
});

describe('buildPage', () => {
  it('builds a page with parsed frontmatter and html', () => {
    const raw = `---
title: T
date: 2024-06-01
tags: [x]
---
# Hi
`;
    const page = buildPage('my-post', raw);
    expect(page.slug).toBe('my-post');
    expect(page.title).toBe('T');
    expect(page.date).toBeInstanceOf(Date);
    expect(page.tags).toEqual(['x']);
    expect(page.html).toContain('<h1');
  });
});

describe('sortByDate', () => {
  it('sorts pages newest first', () => {
    const pages = [
      buildPage('old', '---\ntitle: Old\ndate: 2020-01-01\n---\n'),
      buildPage('new', '---\ntitle: New\ndate: 2023-01-01\n---\n'),
      buildPage('none', '---\ntitle: None\n---\n'),
    ];
    const sorted = sortByDate(pages);
    expect(sorted.map((p) => p.slug)).toEqual(['new', 'old', 'none']);
  });
});

describe('escapeHtml', () => {
  it('escapes html characters', () => {
    expect(escapeHtml('<a href="x">&')).toBe('&lt;a href=&quot;x&quot;&gt;&amp;');
  });
});

describe('loadPages', () => {
  it('loads and sorts markdown files from a directory', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-load-'));
    fs.writeFileSync(path.join(dir, 'a.md'), '---\ntitle: A\ndate: 2024-01-01\n---\n# A\n');
    fs.writeFileSync(path.join(dir, 'b.md'), '---\ntitle: B\ndate: 2024-02-01\n---\n# B\n');
    fs.writeFileSync(path.join(dir, 'skip.txt'), 'not markdown');
    const pages = loadPages(dir);
    expect(pages.map((p) => p.slug)).toEqual(['b', 'a']);
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('throws when the directory is missing', () => {
    expect(() => loadPages('/does/not/exist')).toThrow();
  });
});

describe('build', () => {
  it('generates index.html and page files sorted by date', () => {
    const content = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-content-'));
    const out = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-out-'));
    fs.writeFileSync(
      path.join(content, 'first.md'),
      '---\ntitle: First\ndate: 2024-01-10\n---\n# First\n'
    );
    fs.writeFileSync(
      path.join(content, 'second.md'),
      '---\ntitle: Second\ndate: 2024-03-01\n---\n# Second\n'
    );

    const pages = build({ contentDir: content, outputDir: out });

    expect(pages.map((p) => p.slug)).toEqual(['second', 'first']);

    const index = fs.readFileSync(path.join(out, 'index.html'), 'utf-8');
    expect(index).toContain('Second');
    expect(index).toContain('First');
    expect(index.indexOf('Second')).toBeLessThan(index.indexOf('First'));

    expect(fs.existsSync(path.join(out, 'first.html'))).toBe(true);
    expect(fs.existsSync(path.join(out, 'second.html'))).toBe(true);
    const pageHtml = fs.readFileSync(path.join(out, 'second.html'), 'utf-8');
    expect(pageHtml).toContain('<h1>Second</h1>');

    fs.rmSync(content, { recursive: true, force: true });
    fs.rmSync(out, { recursive: true, force: true });
  });
});

import fs from 'fs';
import os from 'os';
import path from 'path';
import { parseArgs, run } from '../src/cli';

describe('parseArgs', () => {
  it('parses build command with defaults', () => {
    const opts = parseArgs(['node', 'ssg', 'build']);
    expect(opts.command).toBe('build');
    expect(opts.contentDir).toBe('./content');
    expect(opts.outputDir).toBe('./dist');
  });

  it('parses --content and --output flags', () => {
    const opts = parseArgs(['node', 'ssg', 'build', '--content', 'src', '--output', 'site']);
    expect(opts.contentDir).toBe('src');
    expect(opts.outputDir).toBe('site');
  });

  it('parses --flag=value syntax', () => {
    const opts = parseArgs(['node', 'ssg', 'build', '--content=in', '--output=out']);
    expect(opts.contentDir).toBe('in');
    expect(opts.outputDir).toBe('out');
  });
});

describe('run', () => {
  it('builds the site and returns 0', () => {
    const content = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-cli-content-'));
    const out = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-cli-out-'));
    fs.writeFileSync(
      path.join(content, 'hello.md'),
      '---\ntitle: Hello\ndate: 2024-01-01\n---\n# Hello\n'
    );

    const code = run(['node', 'ssg', 'build', '--content', content, '--output', out]);
    expect(code).toBe(0);
    expect(fs.existsSync(path.join(out, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(out, 'hello.html'))).toBe(true);

    fs.rmSync(content, { recursive: true, force: true });
    fs.rmSync(out, { recursive: true, force: true });
  });

  it('returns 1 for an unknown command', () => {
    const code = run(['node', 'ssg', 'serve']);
    expect(code).toBe(1);
  });

  it('returns 1 when content directory is missing', () => {
    const code = run(['node', 'ssg', 'build', '--content', '/does/not/exist']);
    expect(code).toBe(1);
  });
});

